  for (const w of words) freq.set(w, (freq.get(w) || 0) + 1);
  const items = Array.from(freq.entries());
  const used = new Array(items.length).fill(false);
  const res = [];
  for (let t = 0; t < k; t++) {
    let best = -1;
    for (let i = 0; i < items.length; i++) {
      if (used[i]) continue;
      if (best === -1) {
        best = i;
        continue;
      }
      const a = items[i];
      const b = items[best];
      if (a[1] > b[1] || (a[1] === b[1] && a[0] < b[0])) best = i;
    }
    if (best === -1) break;
    used[best] = true;
    res.push(items[best][0]);
  }
  return res;
}

function solve(words, k) {
  const freq = new Map();
  for (const w of words) freq.set(w, (freq.get(w) || 0) + 1);
  const worse = (a, b) => a[1] < b[1] || (a[1] === b[1] && a[0] > b[0]);
  const heap = [];
  const push = (x) => {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (worse(heap[i], heap[p])) {
        const t = heap[p];
        heap[p] = heap[i];
        heap[i] = t;
        i = p;
      } else break;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      while (true) {
        let s = i;
        const l = 2 * i + 1;
        const r = 2 * i + 2;
        if (l < heap.length && worse(heap[l], heap[s])) s = l;
        if (r < heap.length && worse(heap[r], heap[s])) s = r;
        if (s === i) break;
        const t = heap[s];
        heap[s] = heap[i];
        heap[i] = t;
        i = s;
      }
    }
    return top;
  };
  for (const entry of freq.entries()) {
    push(entry);
    if (heap.length > k) pop();
  }
  const res = [];
  while (heap.length > 0) res.push(pop()[0]);
  res.reverse();
  return res;
}
